package dev.thillainirmal.shopops.web;
import jakarta.servlet.*; import jakarta.servlet.http.*; import org.springframework.beans.factory.annotation.Value; import org.springframework.context.annotation.*; import org.springframework.http.*; import org.springframework.security.authentication.UsernamePasswordAuthenticationToken; import org.springframework.security.config.annotation.web.builders.HttpSecurity; import org.springframework.security.config.http.SessionCreationPolicy; import org.springframework.security.core.context.SecurityContextHolder; import org.springframework.security.web.SecurityFilterChain; import org.springframework.security.web.authentication.UsernamePasswordAuthenticationFilter; import org.springframework.web.bind.MethodArgumentNotValidException; import org.springframework.web.bind.annotation.*; import org.springframework.web.filter.OncePerRequestFilter;
import java.io.IOException; import java.nio.charset.StandardCharsets; import java.security.MessageDigest; import java.util.List;
@Configuration
public class ApiConfiguration {
 @Bean SecurityFilterChain security(HttpSecurity http,@Value("${shop.security.api-key}")String key)throws Exception{return http.csrf(c->c.disable()).sessionManagement(s->s.sessionCreationPolicy(SessionCreationPolicy.STATELESS)).authorizeHttpRequests(a->a.requestMatchers("/","/index.html","/favicon.ico","/actuator/health/**","/actuator/prometheus").permitAll().anyRequest().authenticated()).addFilterBefore(new KeyFilter(key),UsernamePasswordAuthenticationFilter.class).build();}
 static class KeyFilter extends OncePerRequestFilter {private final byte[] expected;KeyFilter(String key){expected=key.getBytes(StandardCharsets.UTF_8);}protected void doFilterInternal(HttpServletRequest req,HttpServletResponse res,FilterChain chain)throws ServletException,IOException{var value=req.getHeader("X-API-Key");if(value!=null&&MessageDigest.isEqual(expected,value.getBytes(StandardCharsets.UTF_8)))SecurityContextHolder.getContext().setAuthentication(new UsernamePasswordAuthenticationToken("api-client",null,List.of()));chain.doFilter(req,res);}}
 @RestControllerAdvice static class Errors {@ExceptionHandler({IllegalArgumentException.class})ProblemDetail bad(RuntimeException e){return ProblemDetail.forStatusAndDetail(HttpStatus.BAD_REQUEST,e.getMessage());}@ExceptionHandler({IllegalStateException.class})ProblemDetail conflict(IllegalStateException e){return ProblemDetail.forStatusAndDetail(e.getMessage().startsWith("AI assistant")?HttpStatus.SERVICE_UNAVAILABLE:HttpStatus.CONFLICT,e.getMessage());}@ExceptionHandler(MethodArgumentNotValidException.class)ProblemDetail validation(MethodArgumentNotValidException e){return ProblemDetail.forStatusAndDetail(HttpStatus.BAD_REQUEST,"Request validation failed");}}
}
